type listViewWhere[Q psql.Filterable] struct {
	cols        listViewColumns
	ID          psql.WhereMod[Q, string]
	CreatedAt   psql.WhereMod[Q, time.Time]
	UpdatedAt   psql.WhereMod[Q, time.Time]
	ContainerID psql.WhereMod[Q, string]
	Name        psql.WhereMod[Q, string]
	Columns     psql.WhereMod[Q, types.JSON[[]string]]
	Query       psql.WhereMod[Q, types.JSON[json.RawMessage]]
	Layout      psql.WhereMod[Q, string]
	IsDefault   psql.WhereMod[Q, bool]
	Version     psql.WhereMod[Q, int64]
	R           listViewWhereR[Q]
}

func (listViewWhere[Q]) AliasedAs(alias string) listViewWhere[Q] {
	return buildListViewWhere[Q](buildListViewColumns(alias))
}

func buildListViewWhere[Q psql.Filterable](cols listViewColumns) listViewWhere[Q] {
	return listViewWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:   psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		ContainerID: psql.Where[Q, string](cols.ContainerID.Expression),
		Name:        psql.Where[Q, string](cols.Name.Expression),
		Columns:     psql.Where[Q, types.JSON[[]string]](cols.Columns.Expression),
		Query:       psql.Where[Q, types.JSON[json.RawMessage]](cols.Query.Expression),
		Layout:      psql.Where[Q, string](cols.Layout.Expression),
		IsDefault:   psql.Where[Q, bool](cols.IsDefault.Expression),
		Version:     psql.Where[Q, int64](cols.Version.Expression),
		R:           listViewWhereR[Q]{cols: cols},
	}
}

// listViewWhereR holds the relationship-based filters of
// listViewWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type listViewWhereR[Q psql.Filterable] struct {
	cols listViewColumns
}

// HasContainerResource filters parents that have a matching ContainerResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w listViewWhereR[Q]) HasContainerResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.ContainerID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}
